import io
import logging
import os
import shutil
import sys
import tempfile
from contextlib import contextmanager
from typing import IO, Iterator, Optional, Tuple, Union
from .records import Record, scan_records
log = logging.getLogger(__name__)
if sys.version_info >= (3, 6):
    _FilePath = os.PathLike
else:
    _FilePath = str

def report_invalid_records(records: Iterator[Record]) -> Iterator[Record]:
    for record in records:
        if record.invalid:
            log.warning('Unrecognized settings record at line %s', record.source_text.line)
        yield record

@contextmanager
def staged_edit(path: Union[str, _FilePath]) -> Iterator[Tuple[IO[str], IO[str]]]:
    try:
        if not os.path.isfile(path):
            with io.open(path, 'w+') as incoming:
                incoming.write('')
        with tempfile.NamedTemporaryFile(mode='w+', delete=False) as outgoing:
            with io.open(path) as incoming:
                yield (incoming, outgoing)
    except BaseException:
        if os.path.isfile(outgoing.name):
            os.unlink(outgoing.name)
        raise
    else:
        shutil.move(outgoing.name, path)

def store_value(settings_path: Union[str, _FilePath], name_to_store: str, text_to_store: str, quote_style: str='always', export_entry: bool=False) -> Tuple[Optional[bool], str, str]:
    if quote_style not in ('always', 'auto', 'never'):
        raise ValueError('Unsupported quoting style: {}'.format(quote_style))
    use_quotes = quote_style == 'always' or (quote_style == 'auto' and (not text_to_store.isalnum()))
    if use_quotes:
        encoded_value = "'{}'".format(text_to_store.replace("'", "\\'"))
    else:
        encoded_value = text_to_store
    if export_entry:
        new_record = 'export {}={}\n'.format(name_to_store, encoded_value)
    else:
        new_record = '{}={}\n'.format(name_to_store, encoded_value)
    with staged_edit(settings_path) as (incoming, outgoing):
        updated = False
        for record in report_invalid_records(scan_records(incoming)):
            if record.name == name_to_store:
                outgoing.write(new_record)
                updated = True
            else:
                outgoing.write(record.source_text.text)
        if not updated:
            outgoing.write(new_record)
    return (True, name_to_store, text_to_store)

