import codecs
import re
from typing import IO, Iterator, Match, NamedTuple, Optional, Pattern, Sequence, Tuple

def compile_token(text: str, extra_flags: int=0) -> Pattern[str]:
    return re.compile(text, re.UNICODE | extra_flags)
_line_break = compile_token('(\\r\\n|\\n|\\r)')
_record_space = compile_token('\\s*', extra_flags=re.MULTILINE)
_inline_space = compile_token('[^\\S\\r\\n]*')
_prefix_token = compile_token('(?:export[^\\S\\r\\n]+)?')
_quoted_name = compile_token("'([^']+)'")
_bare_name = compile_token('([^=\\#\\s]+)')
_assignment_token = compile_token('(=[^\\S\\r\\n]*)')
_single_value = compile_token("'((?:\\\\'|[^'])*)'")
_double_value = compile_token('"((?:\\\\"|[^"])*)"')
_bare_value = compile_token('([^\\r\\n]*)')
_comment_token = compile_token('(?:[^\\S\\r\\n]*#[^\\r\\n]*)?')
_record_end = compile_token('[^\\S\\r\\n]*(?:\\r\\n|\\n|\\r|$)')
_discard_tail = compile_token('[^\\r\\n]*(?:\\r|\\n|\\r\\n)?')
_double_escapes = compile_token('\\\\[\\\\\'\\"abfnrtv]')
_single_escapes = compile_token("\\\\[\\\\']")
SourceText = NamedTuple('SourceText', [('text', str), ('line', int)])
Record = NamedTuple('Record', [('name', Optional[str]), ('value', Optional[str]), ('source_text', SourceText), ('invalid', bool)])

class Cursor:

    def __init__(self, offset: int, line: int) -> None:
        self.offset = offset
        self.line = line

    @classmethod
    def start(cls) -> 'Cursor':
        return cls(offset=0, line=1)

    def set(self, other: 'Cursor') -> None:
        self.offset = other.offset
        self.line = other.line

    def advance(self, text: str) -> None:
        self.offset += len(text)
        self.line += len(re.findall(_line_break, text))

class ScanError(Exception):
    pass

class Scanner:

    def __init__(self, stream: IO[str]) -> None:
        self.text = stream.read()
        self.cursor = Cursor.start()
        self.checkpoint = Cursor.start()

    def has_more(self) -> bool:
        return self.cursor.offset < len(self.text)

    def remember(self) -> None:
        self.checkpoint.set(self.cursor)

    def remembered(self) -> SourceText:
        return SourceText(text=self.text[self.checkpoint.offset:self.cursor.offset], line=self.checkpoint.line)

    def peek(self, count: int) -> str:
        return self.text[self.cursor.offset:self.cursor.offset + count]

    def read(self, count: int) -> str:
        result = self.text[self.cursor.offset:self.cursor.offset + count]
        if len(result) < count:
            raise ScanError('The record ended before the requested text.')
        self.cursor.advance(result)
        return result

    def consume(self, regex: Pattern[str]) -> Sequence[str]:
        match = regex.match(self.text, self.cursor.offset)
        if match is None:
            raise ScanError('The next token did not match.')
        self.cursor.advance(self.text[match.start():match.end()])
        return match.groups()

def unescape(regex: Pattern[str], text: str) -> str:

    def unescape_hit(match: Match[str]) -> str:
        return codecs.decode(match.group(0), 'unicode-escape')
    return regex.sub(unescape_hit, text)

def scan_name(scanner: Scanner) -> Optional[str]:
    char = scanner.peek(1)
    if char == '#':
        return None
    elif char == "'":
        name, = scanner.consume(_quoted_name)
    else:
        name, = scanner.consume(_bare_name)
    return name

def scan_bare_value(scanner: Scanner) -> str:
    part, = scanner.consume(_bare_value)
    return re.sub('\\s+#.*', '', part).rstrip()

def scan_value(scanner: Scanner) -> str:
    char = scanner.peek(1)
    if char == u"'":
        value, = scanner.consume(_single_value)
        return unescape(_single_escapes, value)
    elif char == u'"':
        value, = scanner.consume(_double_value)
        return unescape(_double_escapes, value)
    elif char in (u'', u'\n', u'\r'):
        return u''
    else:
        return scan_bare_value(scanner)

def scan_record(scanner: Scanner) -> Record:
    scanner.remember()
    try:
        scanner.consume(_record_space)
        if not scanner.has_more():
            return Record(name=None, value=None, source_text=scanner.remembered(), invalid=False)
        scanner.consume(_prefix_token)
        name = scan_name(scanner)
        scanner.consume(_inline_space)
        if scanner.peek(1) == '=':
            scanner.consume(_assignment_token)
            value = scan_value(scanner)
        else:
            value = None
        scanner.consume(_comment_token)
        scanner.consume(_record_end)
        return Record(name=name, value=value, source_text=scanner.remembered(), invalid=False)
    except ScanError:
        scanner.consume(_discard_tail)
        return Record(name=None, value=None, source_text=scanner.remembered(), invalid=True)

def scan_records(stream: IO[str]) -> Iterator[Record]:
    scanner = Scanner(stream)
    while scanner.has_more():
        yield scan_record(scanner)

