import re
from typing import AnyStr, Optional, Tuple
from .rules import TextRule
_TEXT_CODEC = 'latin1'
_DIRECTORY_GROUP = 'directory_edge'

class RuleSyntaxError(ValueError):
    pass

class PathRule(TextRule):
    __slots__ = ()

    @classmethod
    def compile_text(cls, expression: AnyStr) -> Tuple[Optional[AnyStr], Optional[bool]]:
        if isinstance(expression, str):
            output_type = str
        elif isinstance(expression, bytes):
            output_type = bytes
            expression = expression.decode(_TEXT_CODEC)
        else:
            raise TypeError(f'expression {expression!r} must be text or bytes.')
        original_expression = expression
        if expression.endswith('\\ '):
            expression = expression.lstrip()
        else:
            expression = expression.strip()
        if expression.startswith('#'):
            compiled = None
            decision = None
        elif expression == '/':
            compiled = None
            decision = None
        elif expression:
            if expression.startswith('!'):
                decision = False
                expression = expression[1:]
            else:
                decision = True
            special_expression = None
            pieces = expression.split('/')
            directory_only = not pieces[-1]
            for i in range(len(pieces) - 1, 0, -1):
                prev = pieces[i - 1]
                seg = pieces[i]
                if prev == '**' and seg == '**':
                    del pieces[i]
            if len(pieces) == 2 and pieces[0] == '**' and (not pieces[1]):
                special_expression = f'^.+(?P<{_DIRECTORY_GROUP}>/).*$'
            if not pieces[0]:
                del pieces[0]
            elif len(pieces) == 1 or (len(pieces) == 2 and (not pieces[1])):
                if pieces[0] != '**':
                    pieces.insert(0, '**')
            else:
                pass
            if not pieces:
                raise RuleSyntaxError(f'Malformed path rule: {original_expression!r}')
            if not pieces[-1] and len(pieces) > 1:
                pieces[-1] = '**'
            if special_expression is None:
                output = ['^']
                needs_separator = False
                end = len(pieces) - 1
                for i, seg in enumerate(pieces):
                    if seg == '**':
                        if i == 0 and i == end:
                            output.append(f'[^/]+(?:/.*)?')
                        elif i == 0:
                            output.append('(?:.+/)?')
                            needs_separator = False
                        elif i == end:
                            if directory_only:
                                output.append(f'(?P<{_DIRECTORY_GROUP}>/).*')
                            else:
                                output.append(f'/.*')
                        else:
                            output.append('(?:/.+)?')
                            needs_separator = True
                    elif seg == '*':
                        if needs_separator:
                            output.append('/')
                        output.append('[^/]+')
                        if i == end:
                            output.append(f'(?:(?P<{_DIRECTORY_GROUP}>/).*)?')
                        needs_separator = True
                    else:
                        if needs_separator:
                            output.append('/')
                        try:
                            output.append(cls._compile_piece(seg))
                        except ValueError as e:
                            raise RuleSyntaxError(f'Malformed path rule: {original_expression!r}') from e
                        if i == end:
                            output.append(f'(?:(?P<{_DIRECTORY_GROUP}>/).*)?')
                        needs_separator = True
                output.append('$')
                compiled = ''.join(output)
            else:
                compiled = special_expression
        else:
            compiled = None
            decision = None
        if compiled is not None and output_type is bytes:
            compiled = compiled.encode(_TEXT_CODEC)
        return (compiled, decision)

    @staticmethod
    def _compile_piece(expression: str) -> str:
        escape = False
        compiled = ''
        i, end = (0, len(expression))
        while i < end:
            char = expression[i]
            i += 1
            if escape:
                escape = False
                compiled += re.escape(char)
            elif char == '\\':
                escape = True
            elif char == '*':
                compiled += '[^/]*'
            elif char == '?':
                compiled += '[^/]'
            elif char == '[':
                j = i
                if j < end and (expression[j] == '!' or expression[j] == '^'):
                    j += 1
                if j < end and expression[j] == ']':
                    j += 1
                while j < end and expression[j] != ']':
                    j += 1
                if j < end:
                    j += 1
                    expr = '['
                    if expression[i] == '!':
                        expr += '^'
                        i += 1
                    elif expression[i] == '^':
                        expr += '^'
                        i += 1
                    expr += expression[i:j].replace('\\', '\\\\')
                    compiled += expr
                    i = j
                else:
                    compiled += '\\['
            else:
                compiled += re.escape(char)
        if escape:
            raise ValueError(f'Dangling escape in path rule: {expression!r}')
        return compiled

    @staticmethod
    def escape(s: AnyStr) -> AnyStr:
        if isinstance(s, str):
            output_type = str
            string = s
        elif isinstance(s, bytes):
            output_type = bytes
            string = s.decode(_TEXT_CODEC)
        else:
            raise TypeError(f'input {s!r} must be text or bytes.')
        special_characters = '[]!*#?'
        escaped_text = ''.join(('\\' + x if x in special_characters else x for x in string))
        if output_type is bytes:
            return escaped_text.encode(_TEXT_CODEC)
        else:
            return escaped_text

