                            raise RuleSyntaxError(f'Malformed path rule: {original_expression!r}') from e
                        if i == end:
                            output.append(f'(?:(?P<{_DIRECTORY_GROUP}>/).*)?')
                        needs_separator = True
                output.append('$')
                compiled = ''.join(output)
            else:
                compiled = special_expression
        else:
            compiled = None
            decision = None
        if compiled is not None and output_type is bytes:
            compiled = compiled.encode(_TEXT_CODEC)
        return (compiled, decision)

    @staticmethod
    def _compile_piece(expression: str) -> str:
        escape = False
        compiled = ''
        i, end = (0, len(expression))
        while i < end:
            char = expression[i]
            i += 1
            if escape:
                escape = False
                compiled += re.escape(char)
            elif char == '\\':
                escape = True
            elif char == '*':
                compiled += '[^/]*'
            elif char == '?':
                compiled += '[^/]'
            elif char == '[':
                j = i
                if j < end and (expression[j] == '!' or expression[j] == '^'):
                    j += 1
                if j < end and expression[j] == ']':
                    j += 1
                while j < end and expression[j] != ']':
                    j += 1
                if j < end:
                    j += 1
                    expr = '['
                    if expression[i] == '!':
                        expr += '^'
                        i += 1
                    elif expression[i] == '^':
                        expr += '^'
                        i += 1
                    expr += expression[i:j].replace('\\', '\\\\')
                    compiled += expr
                    i = j
                else:
                    compiled += '\\['
            else:
                compiled += re.escape(char)
        if escape:
            raise ValueError(f'Dangling escape in path rule: {expression!r}')
        return compiled

    @staticmethod
    def escape(s: AnyStr) -> AnyStr:
        if isinstance(s, str):
            output_type = str
            string = s
        elif isinstance(s, bytes):
            output_type = bytes
            string = s.decode(_TEXT_CODEC)
        else:
            raise TypeError(f'input {s!r} must be text or bytes.')
        special_characters = '[]!*#?'
        escaped_text = ''.join(('\\' + x if x in special_characters else x for x in string))
        if output_type is bytes:
            return escaped_text.encode(_TEXT_CODEC)
        else:
            return escaped_text
